echo "  2) git commit -m \"fix(planificador,facturacion,driver-app): comparativa transportistas y asignacion directa desbloqueadas tras db push, todas las rutas del dia visibles en la App Conductor, generacion de liquidaciones + informe de gasto por defecto, transportista subcontratado rellenable en el DeCA, OTD/OTS junto a OTIF en Analitica (Fase 8Y)\""
echo "  3) git push"
echo "  4) IMPORTANTE -- en Cloud Shell: git pull origin main  (siempre antes de db push)"
echo "  5) En Cloud Shell: npx prisma db push"
echo "     -- esto es lo que arregla \"Comparar transportistas\" y \"asignar transportista directamente\":"
echo "        la Fase 8X ya anadio Carrier.address/postalCode/phone al codigo, pero si la base de"
echo "        datos de produccion no tiene todavia esas 3 columnas, cualquier consulta que traiga"
echo "        el transportista completo (comparar, listar transportistas, gestionar ruta) devuelve"
echo "        error 500. Este db push tambien anade las 4 columnas nuevas de Route (subcontratado)."
